contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking the payment amount as parameter
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // we need some Ether to send when calling play
        require(address(this).balance >= amount);

        // read before-values
        uint pot_before = c.pot(); if (__ESBMC_reverted()) return;
        uint bal_before = address(c).balance;

        // call play and catch revert
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-values
        uint pot_after = c.pot(); if (__ESBMC_reverted()) return;
        uint bal_after = address(c).balance;

        // General rule: If the call succeeded and the sent amount equals the ticket price (10), then
        // either the pot increased by 10 (no payout), or the pot was reset to 0 (a payout occurred).
        // We express this as a single assert over observable values.
        assert(reverted || amount != 10 || (pot_after == pot_before + 10 || pot_after == 0));
    }

    // accept Ether when contract receives payout calls
    receive() external payable {}
}

